{
  "components": [
    {
      "type": "claim",
      "quote": "Once the above procedure has been concluded, the SFOE finalises the detailed plan and initiates a consultation of public authorities.",
      "gist": "SFOE finalises plan and starts public consultation after completing prior procedure."
    },
    {
      "type": "number",
      "quote": "two months",
      "gist": "Two months timeframe after consultation concludes."
    },
    {
      "type": "obligation",
      "quote": "the SFOE petitions the Federal Council to specify the planning zone",
      "gist": "SFOE must petition Federal Council to specify planning zone within two months."
    },
    {
      "type": "condition",
      "quote": "In cases in which the scope for more than one planning zone is deemed insufficient",
      "gist": "If scope for multiple planning zones is insufficient."
    },
    {
      "type": "obligation",
      "quote": "the applicant may, with the consent of the involved cantons, submit a proposal to the SFOE for a single planning zone",
      "gist": "Applicant can submit single planning zone proposal to SFOE with cantonal consent."
    },
    {
      "type": "obligation",
      "quote": "the SFOE may waive a formal specification of the planning zone",
      "gist": "SFOE can choose to waive formal planning zone specification."
    }
  ]
}
